"""Targeted owner pass over verified closed NOX build archives."""

import base64
from collections import Counter
import fcntl
from hashlib import sha256
import json
import os
from pathlib import Path
import re
import time
from types import ModuleType


BUNDLE = {"installed_cache_gate.py": "", "archive_storage.py": "", "archive_release.py": ""}
BOOT = '9c0ecc02-85c1-452b-b8ae-521e9a11fd03'
WINDOW = 512 * 1024**2
CAP = 2 * 1024**3
TARGET = CAP + 256 * 1024**2
PINS = {
    'installed_cache_gate.py': '21f63f5b57d6838aca4adec15beff7b63218c9ad70cd87f9f69a45e840d249c7',
    'archive_storage.py': 'a7dc06f9fa2b6e2220b576236056e43402dbb0a4a8f17d44d7eea06223374515',
    'archive_release.py': '0710b40a3655a6e0a812753ad779d868412f354e916f2f0198ef1558a3d57d6e',
}


def require(ok, reason):
    if not ok:
        raise RuntimeError('HOLD_CHAT_ARCHIVE_CACHE_' + reason)


def load(name):
    data = base64.b64decode(BUNDLE[name], validate=True)
    require(0 < len(data) <= 256 * 1024 and sha256(data).hexdigest() == PINS[name], 'BUNDLE_PIN')
    if name == 'archive_release.py':
        source = data.decode()
        edits = (
            ('FILE_RANGE_BYTES = 128 * 1024**2', 'FILE_RANGE_BYTES = 512 * 1024**2'),
            ('archive_only=False,\n                     before_advice=None):',
             'archive_only=False,\n                     before_advice=None, offset=PAGE_BYTES):'),
            ('info.st_size - PAGE_BYTES, FILE_RANGE_BYTES, remaining',
             'info.st_size - offset, FILE_RANGE_BYTES, remaining'),
            ('before = resident_bytes(fd, PAGE_BYTES, length)',
             'before = resident_bytes(fd, offset, length)\n'
             '        if before == 0:\n'
             '            return {"attempted_range_bytes": 0, "observed_resident_before_bytes": 0,\n'
             '                    "observed_resident_after_bytes": 0, "observed_residency_reduction_bytes": 0}'),
            ('os.posix_fadvise(fd, PAGE_BYTES, length, os.POSIX_FADV_DONTNEED)',
             'os.posix_fadvise(fd, offset, length, os.POSIX_FADV_DONTNEED)'),
            ('after = resident_bytes(fd, PAGE_BYTES, length)', 'after = resident_bytes(fd, offset, length)'),
        )
        for old, new in edits:
            require(source.count(old) == 1, 'BUNDLE_ANCHOR')
            source = source.replace(old, new, 1)
        data = source.encode()
    module = ModuleType(name.removesuffix('.py'))
    module.__file__ = name
    exec(compile(data, name, 'exec'), module.__dict__)
    return module


def release(storage, policy, governor, candidates, admit):
    deadline = time.monotonic() + 35
    totals, holds = Counter(), Counter()
    seen = 0
    with storage.reclaim_locks():
        admit()
        before = policy.memory_counters(governor.sample())
        current = before
        remaining = CAP
        page = policy.PAGE_BYTES
        largest = max((row['identity'][2] for row in candidates), default=0)
        # Interleave archives so a single cold large file cannot take every window.
        for offset in range(page, largest - page + 1, WINDOW):
            for row in candidates:
                limit = min(WINDOW, remaining, row['identity'][2] - offset)
                limit -= limit % page
                if limit < page:
                    continue
                if (time.monotonic() >= deadline or seen >= 32
                        or current['headroom_bytes'] >= TARGET
                        or (current['oom'], current['oom_kill']) != (before['oom'], before['oom_kill'])):
                    break
                seen += 1
                remaining -= limit  # Account for an interrupted post-advice observation.
                try:
                    result = policy.advise_candidate(storage, row, deadline, limit,
                        archive_only=True, before_advice=admit, offset=offset)
                except (OSError, RuntimeError) as error:
                    reason = str(error)
                    key = reason if re.fullmatch(r'HOLD_[A-Z_0-9]+', reason) else type(error).__name__
                    holds[key] += 1
                    if any(word in key for word in ('STOP', 'CHAT_BUSY', 'SCOPE', 'PROCESS_CHANGED')):
                        return before, policy.memory_counters(governor.sample()), totals, holds, seen
                    if key == 'HOLD_MEMORY_OWNER_FILE_NOT_ON_ALLOWLISTED_DISK_FILESYSTEM':
                        remaining += limit  # The established policy checks the mount before advice.
                else:
                    remaining += limit - result['attempted_range_bytes']
                    totals.update(result)
                current = policy.memory_counters(governor.sample())
            if (remaining < page or seen >= 32 or time.monotonic() >= deadline
                    or current['headroom_bytes'] >= TARGET
                    or (current['oom'], current['oom_kill']) != (before['oom'], before['oom_kill'])):
                break
        return before, policy.memory_counters(governor.sample()), totals, holds, seen


def main():
    request = os.environ.get('NOX_OWNER_REQUEST_ID', '')
    source = os.environ.get('NOX_OWNER_SOURCE_SHA', '')
    labels = {os.environ[name].removeprefix('C.') for name in ('VAST_CONTAINERLABEL', 'CONTAINER_ID')
              if os.environ.get(name)}
    require(os.geteuid() == 0 and labels == {'60509551'}
            and re.fullmatch(r'[1-9][0-9]{0,19}', request) and re.fullmatch(r'[a-f0-9]{40}', source)
            and Path('/proc/sys/kernel/random/boot_id').read_text().strip() == BOOT, 'OWNER_CONTEXT')
    require(set(BUNDLE) == set(PINS), 'BUNDLE_SCOPE')
    gate, storage, policy = (load(name) for name in PINS)
    with gate.trusted_open(gate.LEASE) as (handle, named):
        stamp = gate.identity(os.fstat(handle.fileno()))
        fcntl.flock(handle.fileno(), fcntl.LOCK_SH | fcntl.LOCK_NB)
        service = gate.assets()
        scope = service.current_scope()

        def admit():
            service.cache.require_stop_clear()
            require(not os.path.lexists('/root/nox/state/MEMORY_STOP.flag'), 'MEMORY_STOP')
            require(service.current_scope() == scope and gate.identity(named()) == stamp, 'SCOPE_CHANGED')
            gate.exact_process(gate.MODEL)
            service.assert_chat_idle()

        admit()
        audit = storage.audit(request, source, archive_only=True, cache_only=True,
                              verified_helper_sha256=PINS['archive_storage.py'])
        coverage = audit['coverage']
        require(len(coverage) == 1 and coverage[0].get('category') == 'NOX_STAGED_ARCHIVES'
                and coverage[0].get('complete') is True
                and audit['process_scan']['complete'] is True, 'INCOMPLETE_CENSUS')
        candidates = audit['cache_advice_candidates'][:32]
        require(all(row['category'] in policy.ARCHIVE_SCOPE for row in candidates), 'ARCHIVE_SCOPE')
        before, after, totals, holds, windows = release(storage, policy, service.governor, candidates, admit)
        gate.exact_process(gate.MODEL)
        require(service.current_scope() == scope, 'SCOPE_CHANGED')
    report = {
        'before': before, 'after': after, 'verified_closed_candidates_in_budget': len(candidates),
        'verified_closed_file_bytes_in_budget': sum(row['identity'][2] for row in candidates),
        'windows_examined': windows, 'outcomes': dict(holds), 'metrics': dict(totals),
        'model_generation_preserved': True, 'target_headroom_bytes': TARGET,
        'target_observed': after['headroom_bytes'] >= TARGET,
        'observed_headroom_delta_bytes': after['headroom_bytes'] - before['headroom_bytes'],
    }
    print('NOX_MAINT_CHAT_ARCHIVE_HEADROOM=' + json.dumps(report, separators=(',', ':')), flush=True)
    print('NOX_MAINT_REPAIR_COMPLETE=true', flush=True)


if __name__ == '__main__':
    try:
        main()
    except (OSError, ValueError, RuntimeError) as error:
        reason = str(error)
        code = reason if re.fullmatch(r'HOLD_[A-Z_0-9]+', reason) else type(error).__name__
        print('NOX_MAINT_CHAT_ARCHIVE_HEADROOM_HOLD=' + code, flush=True)
        raise SystemExit(2) from None
